steps.code:
// Navigate to the provided URL
const url = new URL(input.url);

// Navigate to the URL
navigate(url.href);


// Parse the current page to get story URLs
const { urls } = parse();

// Handle pagination - only on first run (not on reruns)
if (!input.is_rerun) {
    // Default to 2 pages if not specified, max 10 pages
    const max_page = Math.min(input.max_page || 2, 10);

    // Trigger reruns for additional pages
    for (let page = 2; page <= max_page; page++) {
        const next_page_url = new URL(input.url);
        next_page_url.searchParams.set('p', page.toString());

        rerun_stage({
            url: next_page_url.href,
            max_page: input.max_page,
            is_rerun: true
        });
    }
}

// Collect all URLs from the current page
for (let story_url of urls) {
    next_stage({ url: story_url });
}

