    const story_id = $(row).attr('id');

    if (story_id) {
        // Construct the Hacker News discussion URL
        return `https://news.ycombinator.com/item?id=${story_id}`;
    }
    return null;
}).filter(Boolean); // Remove null values

console.log(`Found ${urls.length} story URLs on this page`);

return { urls };

