let comment_count = 0;
if (commentLink && commentLink !== 'discuss') {
  // Extract number from text like "5 comments" or "1 comment"
  comment_count = parseInt(commentLink.replace(/\D/g, '')) || 0;
}

return {
  title,
  url: url ? new URL(url) : null,
  points,
  author,
  comment_count
};

