steps.code:
const base_url = 'https://news.ycombinator.com/';
const url = new URL(input.url || base_url);

// Get current page number from URL parameter
const current_page = parseInt(url.searchParams.get('p')) || 1;

// Navigate to the URL
navigate(url.href);


// Parse the page to extract story URLs
const {story_urls} = parse();

console.log(`Found ${story_urls.length} stories on page ${current_page}`);

// Handle pagination - only trigger reruns on first run (not on rerun)
const max_page = input.max_page || 2;
if (!input.is_rerun && current_page < max_page) {
    // Trigger reruns for subsequent pages
    for (let page = current_page + 1; page <= max_page; page++) {
        const next_url = new URL(base_url);
        next_url.searchParams.set('p', page.toString());
        rerun_stage({
            url: next_url.href,
            max_page: input.max_page,
            is_rerun: true
        });
    }
}

// Collect all story URLs using next_stage
for (let story_url of story_urls) {
    next_stage({url: story_url});
}

