const story_rows = $('tr[id]').toArray().filter(row => {
    const id = $(row).attr('id');
    // Filter out non-story rows (like "bigbox" container)
    return id && /^\d+$/.test(id);
});

console.log(`Found ${story_rows.length} story rows`);

// Extract story IDs and construct Hacker News discussion URLs
const story_urls = story_rows.map(row => {
    const story_id = $(row).attr('id');
    // Construct the Hacker News discussion URL
    return `https://news.ycombinator.com/item?id=${story_id}`;
});

console.log(`Extracted ${story_urls.length} story URLs`);

return {story_urls};

